import {installIntegration} from './integration.js';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>crypto.randomUUID();
const state={boot:null,view:'dashboard',campaignId:localStorage.getItem('grimorio-campaign')||'',entities:[],tab:'character',filters:{},offset:0,recordTabs:[],activeRecord:null,combatId:'',sessionScene:'',pending:0,dirty:false,preview:null,translationPreview:null};
