const nav=[['dashboard','⌂','Visão da campanha'],['campaign','♧','Mundo e personagens'],['scenes','▤','Sessões e cenas'],['encounters','⚔','Encontros'],['session','◈','Mesa de sessão'],['library','▥','Biblioteca'],['treasure','♜','Tesouros'],['imports','⇩','Importações'],['translations','文','Traduções'],['settings','⚙','Dados e backups']];
const kindNames={character:'Personagens',npc:'NPCs',faction:'Facções',location:'Locais',quest:'Missões',clue:'Pistas',timeline:'Linha do tempo',journal:'Diário',document:'Anotações',scene:'Cenas',check:'Testes',encounter:'Encontros',reward:'Recompensas',session:'Sessões'};
const singular={character:'personagem',npc:'NPC',faction:'facção',location:'local',quest:'missão',clue:'pista',timeline:'acontecimento',journal:'entrada no diário',document:'anotação',scene:'cena',check:'teste',encounter:'encontro',reward:'recompensa',session:'sessão'};
const editionLabel=e=>e==='2024'?'5.5 • 2024':e==='2014'?'5e • 2014':e==='caseiro'?'Caseiro':'Edição não identificada';
