const button=(text,action,attrs='',cls='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const activeCampaign=()=>state.boot?.campaigns.find(x=>x.id===state.campaignId);
const hosted=()=>state.boot?.auth?.mode==='github';
const savedLabel=()=>hosted()?'Tudo salvo no servidor':'Tudo salvo neste computador';
function sessionWarning(){if($('#sessionWarning'))return;const el=document.createElement('div');el.id='sessionWarning';el.className='toast error';el.setAttribute('role','alert');el.innerHTML='A sessão expirou. Suas edições continuam nesta tela. <a href="/auth/login" target="_blank" rel="noopener">Entrar em outra aba</a> e depois <button data-action="renew-session">Retomar sessão</button>.';$('#toasts').append(el);}
const all=kind=>state.entities.filter(x=>x.kind===kind);
const entity=eid=>state.entities.find(x=>x.id===eid);
const time=s=>new Date(s).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});
function toast(msg,error=false){const e=document.createElement('div');e.className='toast'+(error?' error':'');e.textContent=msg;$('#toasts').append(e);setTimeout(()=>e.remove(),error?12000:5000);}
async function api(path,data,method=data===undefined?'GET':'POST'){
 state.pending++;updateStatus();
 try{const r=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json','X-Grimorio-Token':state.boot?.token||''},...(data===undefined?{}:{body:JSON.stringify(data)})});const result=await r.json();if(!r.ok){if(r.status===401)sessionWarning();const e=Error(result.error||'Falha na operação.');e.status=r.status;throw e;}return result;}finally{state.pending--;updateStatus();}
}
function updateStatus(text,error=false){const el=$('#saveStatus');if(el){el.textContent=text||(state.pending?'Salvando / consultando…':state.dirty||state.campaignDirty||state.annotationDirty?'Edição pendente…':savedLabel());el.className='save-status'+(error?' error':'');}}
async function refresh(){state.boot=await api('/bootstrap');if(!activeCampaign())state.campaignId=state.boot.campaigns[0]?.id||'';if(state.campaignId)state.entities=await api(`/campaigns/${state.campaignId}/entities`);else state.entities=[];}
function setEntity(e){const i=state.entities.findIndex(x=>x.id===e.id);if(i<0)state.entities.unshift(e);else state.entities[i]=e;}
function head(title,subtitle,actions='',eyebrow='SEU COMPANHEIRO DE MESA'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${h(title)}</h1><p>${h(subtitle)}</p></div>${actions?`<div class="toolbar">${actions}</div>`:''}</div>`;}
function empty(title,text,action=''){return `<div class="empty"><div class="empty-symbol">◇</div><h3>${h(title)}</h3><p>${h(text)}</p>${action}</div>`;}
function needCampaign(){return empty('Abra o primeiro capítulo','Crie uma campanha para organizar seu mundo, preparar encontros e começar a narrar.',button('Criar campanha','new-campaign','','primary'));}
function shell(){
 const c=activeCampaign();
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#dashboard" aria-label="Grimório do Mestre"><svg viewBox="0 0 50 55" fill="none" aria-hidden="true"><path d="M25 3 46 16v24L25 52 4 40V16Z M4 16l21 11 21-11M25 3v24m0 25V27M4 40l21-13 21 13" stroke="currentColor" stroke-width="1.5"/></svg><div><strong>Grimório</strong><span>DO MESTRE</span></div></a><div class="campaign-picker"><span class="eyebrow">CAMPANHA ATIVA</span><select id="campaignSelect" aria-label="Selecionar campanha"><option value="">Selecione uma campanha</option>${state.boot.campaigns.map(x=>`<option value="${h(x.id)}" ${x.id===state.campaignId?'selected':''}>${h(x.name)}</option>`).join('')}</select></div><nav aria-label="Principal">${nav.map(([key,icon,label],i)=>`${i===0?'<div class="nav-group">PREPARAR & NARRAR</div>':i===5?'<div class="nav-group">SEU ACERVO</div>':''}<button title="${label}" class="nav ${state.view===key?'active':''}" data-action="navigate" data-view="${key}" ${state.view===key?'aria-current="page"':''}><span class="icon" aria-hidden="true">${icon}</span><span class="label">${label}</span></button>`).join('')}</nav><div class="sidebar-footer"><span class="online-dot"></span>${hosted()?'ACESSO PESSOAL':'LOCAL & PRIVADO'}<br><span>${hosted()?h(state.boot.auth.user.login):'Seus mundos ficam com você.'}</span><div class="kbd-note">/ buscar · Alt+M mesa · Esc fechar</div></div></aside><div class="workspace"><header class="topbar"><span class="breadcrumb">${h(c?.name||'Seu espaço de aventuras')} <span> / ${h(nav.find(x=>x[0]===state.view)?.[2]||'')}</span></span><div class="top-actions"><span id="saveStatus" class="save-status">${savedLabel()}</span>${badge(editionLabel(c?.data.edition||'2024'),'gold')}${hosted()?button('Sair','logout','','small ghost'):''}${button('⌕ <span class="key">/</span>','quick-search','aria-label="Buscar na biblioteca"','ghost')}</div></header><main class="content" id="content" tabindex="-1"></main></div></div>`;
 renderView();
}
async function navigate(view){if(!await flushSave())return;state.view=view;history.replaceState(null,'','#'+view);shell();}
function renderView(){const f={dashboard:dashboard,campaign:campaignView,scenes:scenesView,encounters:encountersView,session:sessionView,library:libraryView,treasure:treasureView,imports:importsView,translations:translationsView,settings:settingsView};(f[state.view]||dashboard)();}
function dashboard(){
 const c=activeCampaign();
 if(!c){$('#content').innerHTML=head('Toda aventura começa aqui','Uma mesa de trabalho para preparar, consultar e conduzir suas histórias.',button('Nova campanha','new-campaign','','primary'))+`<div class="hero"><div><div class="eyebrow">BEM-VINDO AO SEU GRIMÓRIO</div><h2>Seu mundo. Suas histórias.</h2><p>Biblioteca consultável, cenas preparadas e combate salvo automaticamente. ${hosted()?'Acesso restrito à sua conta, com dados salvos no servidor.':'Tudo neste computador, sem conta.'} Nenhuma chave de IA necessária.</p><div class="toolbar spaced">${button('Criar minha campanha','new-campaign','','primary')}${button('Explorar biblioteca','navigate','data-view="library"')}</div></div><div class="hero-seal">◈</div></div><div class="grid three"><div class="card"><h3>01 · Escolha suas regras</h3><p class="muted spaced">Cada campanha começa em 2024. Fontes e conteúdo de 2014 ficam identificados e podem ser consultados separadamente.</p></div><div class="card"><h3>02 · Traga suas anotações</h3><p class="muted spaced">Importe JSON, Markdown ou texto com prévia. ${hosted()?'Os arquivos que você confirmar serão salvos nesta hospedagem privada.':'Os arquivos ficam neste computador.'}</p></div><div class="card"><h3>03 · Prepare a próxima sessão</h3><p class="muted spaced">Crie cenas, testes, encontros e recompensas. Inicie o combate quando a história pedir.</p></div></div>`;return;}
 const next=all('scene').find(x=>x.data.status!=='concluída');const recent=state.entities.filter(x=>!['combat'].includes(x.kind)).slice(0,5);
 $('#content').innerHTML=head(c.name,c.data.description||'Seu próximo capítulo está esperando.',button('Configurar campanha','edit-campaign')+button('Abrir mesa de sessão','navigate','data-view="session"','primary'),'CADERNO DE CAMPANHA')+`<div class="hero"><div><div class="eyebrow">A PRÓXIMA HISTÓRIA</div><h2>${h(next?.name||'Prepare o que vem a seguir')}</h2><p>${h(next?.data.summary||c.data.premise||'Organize suas cenas e mantenha as possibilidades da aventura ao alcance de um clique.')}</p><div class="toolbar spaced">${next?button('Consultar cena','edit-entity',`data-id="${next.id}"`,'primary'):button('Preparar uma cena','new-entity','data-kind="scene"','primary')}${button('Preparar encontro','new-entity','data-kind="encounter"')}</div></div><div class="hero-seal">⚜</div></div><div class="grid four">${[['character','Personagens no grupo','Níveis e fichas do grupo'],['scene','Cenas preparadas','Narrativas e testes'],['encounter','Encontros disponíveis','Prontos para entrar em cena'],['journal','Registros de sessão','A história até aqui']].map(([kind,label,desc])=>`<div class="card metric"><small>${label}</small><span class="count">${all(kind).length}</span><small>${desc}</small></div>`).join('')}</div><div class="grid two spaced"><section class="card"><div class="card-head"><h2>Seu caderno</h2>${button('Ver mundo →','navigate','data-view="campaign"','small ghost')}</div>${recent.length?recent.map(e=>entryRow(e)).join(''):empty('Um mundo por construir','Adicione personagens, lugares e pistas à sua campanha.',button('Adicionar personagem','new-entity','data-kind="character"'))}</section><section class="card"><div class="card-head"><h2>Ao alcance da mão</h2>${badge(hosted()?'SUA BIBLIOTECA':'SEM INTERNET','teal')}</div><div class="stack">${[['library','▥','Consultar uma regra',`${state.boot.stats.records.toLocaleString('pt-BR')} registros no acervo · originais e traduções`],['scenes','▤','Preparar uma sessão','Cenas, pistas e testes com resultados previstos'],['treasure','♜','Separar as recompensas','Tabelas identificadas e trilha de rolagens'],['settings','⇩','Guardar um backup','Campanhas, biblioteca, notas e traduções']].map(([view,icon,title,desc])=>`<div class="entry-row"><span class="entry-icon">${icon}</span><div class="body"><h3>${title}</h3><p>${h(desc)}</p></div>${button('→','navigate',`data-view="${view}"`,'small ghost')}</div>`).join('')}</div><div class="notice">${h(c.data.houseRules?'Há regras da casa configuradas nesta campanha.':'Dica: defina fontes permitidas e regras da casa nas configurações da campanha.')}</div></section></div>`;
}
function entryRow(e){return `<div class="entry-row"><span class="entry-icon">${e.kind==='character'?'♙':e.kind==='scene'?'▤':e.kind==='encounter'?'⚔':'◇'}</span><div class="body"><h3>${h(e.name)}</h3><p>${h(kindNames[e.kind]||e.kind)}${e.data.level?' · Nível '+h(e.data.level):''}${e.data.status?' · '+h(e.data.status):''}</p></div>${button('Abrir','edit-entity',`data-id="${e.id}"`,'small')}</div>`;}
function campaignView(){
 const c=activeCampaign();$('#content').innerHTML=head('Mundo e personagens','Tudo o que dá vida à campanha, conectado em um só caderno.',button('Nova campanha','new-campaign')+(c?button('Configurar','edit-campaign')+button('+ Adicionar','new-entity',`data-kind="${state.tab}"`,'primary'):''));if(!c){$('#content').innerHTML+=needCampaign();return;}
 const kinds=['character','npc','faction','location','quest','clue','timeline','journal','document'];if(!kinds.includes(state.tab))state.tab='character';
 $('#content').innerHTML+=`<div class="tabs">${kinds.map(k=>button(kindNames[k],'campaign-tab',`data-kind="${k}"`,state.tab===k?'active':'')).join('')}</div><div class="grid two">${all(state.tab).length?all(state.tab).map(e=>`<article class="card"><div class="card-head"><h2>${h(e.name)}</h2>${badge(e.data.status||kindNames[e.kind],e.kind==='character'?'teal':'')}</div><p class="prewrap muted">${h((e.data.body||e.data.summary||'Sem descrição.').slice(0,260))}</p>${e.kind==='character'?`<div class="record-meta spaced">${badge('Nível '+(e.data.level||1),'gold')}${badge('PV '+(e.data.maxHp||10))}${badge(e.data.player||'Jogador não informado')}</div>`:''}<div class="toolbar spaced">${button('Editar','edit-entity',`data-id="${e.id}"`)}${button('Duplicar','duplicate',`data-id="${e.id}"`,'small ghost')}</div>${renderLinks(e.data.links)}</article>`).join(''):empty('Ainda não há '+kindNames[state.tab].toLowerCase(),'Adicione seu conteúdo. Os campos são salvos automaticamente durante a edição.',button('Adicionar '+singular[state.tab],'new-entity',`data-kind="${state.tab}"`,'primary'))}</div>`;
}
function renderLinks(links=[]){return `<div class="link-list">${links.map(x=>{const e=entity(x);return e?button(h(e.name),'edit-entity',`data-id="${h(x)}"`,'small ghost'):button('↗ '+h(x.slice(0,18)),'open-record',`data-id="${h(x)}"`,'small ghost');}).join('')}</div>`;}
function field(name,label,value='',type='text',opts={}){const cls=opts.full?'full':'';const attrs=`name="${h(name)}" ${opts.required?'required':''} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.max!==undefined?`max="${opts.max}"`:''}`;let control;if(type==='textarea'||type==='json')control=`<textarea ${attrs} class="${type==='json'?'json-editor':''}" ${opts.rows?`rows="${opts.rows}"`:''}>${h(value)}</textarea>`;else if(type==='select')control=`<select ${attrs}>${(opts.options||[]).map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${h(v)}" ${String(value)===String(v)?'selected':''}>${h(t)}</option>`;}).join('')}</select>`;else if(type==='checkbox')return `<label class="check ${cls}"><input type="checkbox" ${attrs} ${value?'checked':''}>${h(label)}</label>`;else control=`<input type="${type}" ${attrs} value="${h(value)}">`;return `<label class="${cls}">${h(label)}${control}${opts.help?`<span class="form-help">${h(opts.help)}</span>`:''}</label>`;}
function showModal(title,body){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${h(title)}</h2>${button('✕','close-modal','aria-label="Fechar"','ghost small')}</div><div class="modal-body">${body}</div>`;if($('#entityForm')||$('#campaignForm'))$('.form-footer',d).insertAdjacentHTML('beforeend',button('Descartar alterações não salvas','discard-draft','','small danger'));if(!d.open)d.showModal();}
async function closeModal(){await flushSave();if(state.dirty)return;if(state.campaignDirty)throw Error('Salve a campanha ou descarte as alterações não salvas antes de fechar.');$('#modal').close();renderView();}
function campaignForm(existing){const e=existing||{name:'',data:{edition:'2024',allowHomebrew:false},revision:0};showModal(existing?'Configurar campanha':'Nova campanha',`<form id="campaignForm" data-id="${e.id||''}"><div class="form-grid">${field('name','Nome da campanha',e.name,'text',{required:true,full:true})}${field('edition','Versão principal das regras',e.data.edition,'select',{options:[['2024','D&D 5.5 — regras revisadas de 2024'],['2014','D&D 5e — regras de 2014']]})}${field('allowHomebrew','Permitir conteúdo caseiro',e.data.allowHomebrew,'checkbox')}${field('description','Descrição',e.data.description,'textarea',{full:true})}${field('premise','Premissa',e.data.premise,'textarea',{full:true})}${field('sources','Fontes habilitadas (códigos separados por vírgula)',(e.data.sources||[]).join(', '),'text',{full:true,help:'Vazio permite todas as fontes da edição principal. Exemplos: XPHB, XMM, XDMG.'})}${field('supplements','Suplementos permitidos',(e.data.supplements||[]).join(', '),'text',{full:true})}${field('houseRules','Regras da casa',e.data.houseRules,'textarea',{full:true})}</div><div class="form-footer"><small>2014 e 2024 permanecem identificados. A busca usa estas preferências quando ativadas.</small><button class="primary" type="submit">Salvar campanha</button></div></form>`);}
