 character:[['player','Jogador'],['level','Nível','number',1],['maxHp','PV máximos','number',10],['initiativeBonus','Modificador de iniciativa','number',0],['class','Classe e subclasse'],['species','Espécie / raça'],['active','Participa do grupo ativo','checkbox',true],['body','Ficha resumida, recursos e notas','textarea']],
 npc:[['role','Papel / ocupação'],['faction','Facção'],['motivation','Motivação'],['dialogue','Diálogos','textarea'],['body','Descrição e relações','textarea']],
