 'duplicate':async b=>{const e=entity(b.dataset.id);const saved=await api(`/entities/${e.id}/duplicate`,{name:e.name+' (cópia)',template:e.data.template||false});setEntity(saved);toast('Cópia criada.');renderView();},
 'undo-entity':async b=>{clearTimeout(saveTimer);const e=entity(b.dataset.id);const saved=await api(`/entities/${e.id}/undo`,{revision:e.revision});setEntity(saved);state.dirty=false;entityForm(saved.kind,saved);toast('Última edição desfeita.');},
 'choose-link':()=>{const f=$('#entityForm');const select=document.createElement('select');select.setAttribute('aria-label','Escolher elemento para vincular');select.innerHTML='<option value="">Escolha um elemento para vincular</option>'+state.entities.filter(x=>x.id!==f.dataset.id&&!['combat','sessionlog'].includes(x.kind)).map(x=>`<option value="${x.id}">${h(kindNames[x.kind]||x.kind)} — ${h(x.name)}</option>`).join('');select.addEventListener('change',()=>{if(!select.value)return;const area=$('[name=links]',f);area.value=[area.value,select.value].filter(Boolean).join('\n');scheduleSave();select.remove();});f.querySelector('.form-grid').append(select);},
 'choose-library-link':async()=>{const f=$('#entityForm');const wrapper=document.createElement('div');wrapper.className='full card';wrapper.innerHTML='<label>Buscar registro para vincular<input placeholder="Nome original ou traduzido" aria-label="Buscar vínculo na biblioteca"></label><div class="stack spaced"></div>';f.querySelector('.form-grid').append(wrapper);let timer;wrapper.querySelector('input').addEventListener('input',ev=>{clearTimeout(timer);timer=setTimeout(async()=>{try{const r=await api('/records?'+new URLSearchParams({q:ev.target.value,limit:10,preferredEdition:activeCampaign().data.edition}));const results=wrapper.querySelector('div');results.innerHTML=r.results.map(x=>`<button type="button" data-record-link="${x.id}">${h(x.annotation.namePt||x.name)} · ${h(x.source)} · ${h(x.edition)}</button>`).join('');}catch(e){toast(e.message,true);}},300);});wrapper.addEventListener('click',ev=>{const b=ev.target.closest('[data-record-link]');if(b){const area=$('[name=links]',f);area.value=[area.value,b.dataset.recordLink].filter(Boolean).join('\n');scheduleSave();wrapper.remove();}});},
 'build-encounter':b=>buildEncounter(b.dataset.id),
 'search-monster':async()=>{const q=$('#monsterQuery').value;const c=activeCampaign();const sources=[...(c.data.sources||[]),...(c.data.supplements||[])];const r=await api('/records?'+new URLSearchParams({category:'monster',q,edition:c.data.edition,includeHomebrew:String(!!c.data.allowHomebrew),...(sources.length?{allowedSources:sources.join(',')}:{}),limit:30}));$('#monsterResults').innerHTML=r.results.length?r.results.map(x=>`<div class="entry-row"><div class="body"><b>${h(x.annotation.namePt||x.name)}</b><p>ND ${h(x.facets.cr)} · ${h(x.source)} · ${h(x.edition)}</p></div>${button('Ficha','open-record',`data-id="${x.id}"`,'small')}${button('Adicionar','add-monster',`data-id="${x.id}"`,'small primary')}</div>`).join(''):empty('Nenhuma criatura encontrada','Use o nome original ou importe uma fonte habilitada na campanha.');},
 'add-monster':async b=>{const r=await api('/records/'+b.dataset.id);const e=entity(state.buildEncounterId);const m={recordId:r.id,name:r.annotation.namePt||r.name,cr:r.facets.cr,source:r.source,edition:r.edition,quantity:1,maxHp:r.raw.hp?.average||null,side:'enemy'};const xp=r.raw.cr?.xp??r.raw.xp;if(typeof xp==='number')m.xp=xp;await persistMonsters([...(e.data.monsters||[]),m]);toast('Criatura adicionada.');},
 'remove-monster':async b=>{const list=[...(entity(state.buildEncounterId).data.monsters||[])];list.splice(Number(b.dataset.index),1);await persistMonsters(list);},
 'adjust-monster':b=>{const index=Number(b.dataset.index);const m=entity(state.buildEncounterId).data.monsters[index];const div=document.createElement('div');div.className='card spaced';div.id='adjustMonster';div.innerHTML=`<h3>Ajustar ${h(m.name)}</h3><form id="adjustMonsterForm" data-index="${index}" class="spaced"><div class="form-grid">${field('maxHp','PV máximos',m.maxHp||1,'number',{min:1})}${field('xp','XP ajustado (vazio usa ND)',m.xp??'','number',{min:0})}${field('side','Lado',m.side,'select',{options:[['enemy','Adversário'],['ally','Aliado']]})}${field('countForMultiplier','Conta no multiplicador de 2014',m.countForMultiplier!==false,'checkbox')}${field('notes','Variante e ajustes',m.notes||'','textarea',{full:true})}</div><div class="toolbar spaced"><button type="submit" class="primary">Salvar ajuste</button></div></form>`;$('#adjustMonster')?.remove();$('#monsterRows').after(div);},
 'evaluate-encounter':b=>evaluate(b.dataset.id),
 'start-combat':async b=>{const e=entity(b.dataset.id);const mixed=(e.data.monsters||[]).some(x=>x.edition&&x.edition!==activeCampaign().data.edition);if(mixed&&!b.dataset.confirmed){showModal('Encontro com edições diferentes',`<p>Há criaturas que não pertencem à edição principal ${h(activeCampaign().data.edition)}. Essa combinação exige sua decisão explícita para este combate.</p><div class="toolbar spaced">${button('Iniciar este combate com as edições indicadas','start-combat',`data-id="${e.id}" data-confirmed="true"`,'primary')}</div>`);return;}const combat=await api('/combat/start',{encounterId:e.id,allowMixed:mixed});setEntity(combat);state.combatId=combat.id;$('#modal').close();await navigate('session');toast('Combate iniciado e salvo.');},
 'combat-action':b=>combatAction(b.dataset.id,{type:b.dataset.type}),
