 'add-combatant':b=>showModal('Adicionar participante',`<form id="addCombatantForm" data-combat="${b.dataset.id}"><div class="form-grid">${field('name','Nome','','text',{required:true})}${field('side','Lado','enemy','select',{options:[['enemy','Adversário'],['ally','Aliado']]})}${field('maxHp','PV máximos',10,'number',{min:1})}${field('initiative','Iniciativa manual',0,'number')}${field('group','Grupo')}</div><div class="toolbar spaced"><button type="submit" class="primary">Adicionar</button></div></form>`),
 'undo-combat':async b=>{const e=entity(b.dataset.id);const saved=await api(`/entities/${e.id}/undo`,{revision:e.revision});setEntity(saved);state.combatId=e.id;sessionView();toast('Ação de combate desfeita.');},
