 'session-rule-search':async()=>{const r=await api('/records?'+new URLSearchParams({q:$('#sessionRuleQuery').value,edition:activeCampaign().data.edition,limit:12}));$('#sessionRuleResults').innerHTML=r.results.map(recordCard).join('')||'<p class="muted">Regra não encontrada no conteúdo importado desta edição.</p>';},
 'save-session-journal':async()=>{const logs=all('sessionlog')[0]?.data.entries||[];if(!logs.length)return toast('Ainda não há acontecimentos para registrar.',true);const saved=await api('/entities',{campaign_id:state.campaignId,kind:'journal',name:'Sessão — '+new Date().toLocaleDateString('pt-BR'),data:{date:new Date().toISOString().slice(0,10),body:logs.map(x=>`${time(x.at)} — ${x.note}`).join('\n'),links:[]}});setEntity(saved);toast('Acontecimentos copiados para o diário.');},
