 'toggle-favorite':async b=>{await saveAnnotationForm();const r=state.recordTabs.find(x=>x.id===b.dataset.id);const saved=await api(`/records/${r.id}/annotation`,{...r.annotation,favorite:!r.annotation.favorite},'PUT');state.recordTabs=state.recordTabs.map(x=>x.id===r.id?{...x,annotation:saved.annotation}:x);renderReader({...r,annotation:saved.annotation});if(state.view==='library')loadLibrary();},
 'reference-lookup':b=>lookupReference(b.dataset.name,b.dataset.category,b.dataset.source),
 'link-record':async b=>{if(!activeCampaign())return toast('Crie uma campanha primeiro.',true);const r=state.recordTabs.find(x=>x.id===b.dataset.id);const saved=await api('/entities',{campaign_id:state.campaignId,kind:'document',name:'Referência — '+(r.annotation.namePt||r.name),data:{body:`${r.name} — ${r.source}${r.page?' p. '+r.page:''} (${r.edition})`,links:[r.id]}});setEntity(saved);toast('Referência adicionada às anotações da campanha.');},
 'clear-filters':()=>{state.filters={campaignPrefs:false};state.offset=0;libraryView();},
