 'coverage':coverage,
 'apply-import':async()=>{const p=state.preview;const selectedIds=$$('.import-selected:checked').map(x=>x.value);const r=await api('/import/apply',{previewId:p.previewId,selectedIds,updateExisting:!!$('#updateExisting')?.checked});toast(`Importação aplicada: ${r.added} novos, ${r.updated} atualizados, ${r.entities} elementos de campanha.`);state.preview=null;await refresh();importsView();},
 'cancel-import':()=>{state.preview=null;$('#importPreview').innerHTML='';},
 'add-glossary':()=>showModal('Termo do glossário',`<form id="glossaryForm"><div class="form-grid">${field('term','Termo original','','text',{required:true})}${field('translation','Tradução preferida em PT-BR','','text',{required:true})}${field('note','Observação / convenção','','textarea',{full:true})}</div><div class="toolbar spaced"><button type="submit" class="primary">Salvar termo</button></div></form>`),
 'export-translations':async()=>{const r=await api('/records?'+new URLSearchParams({...queryFilters(),limit:100,offset:0}));const b=await api('/translation/export',{ids:r.results.map(x=>x.id)});download('lote-traducoes.json',b);toast(`${b.records.length} registros sem tradução exportados. Nenhum serviço externo foi acessado.`);},
 'apply-translations':async()=>{const r=await api('/translation/apply',{previewId:state.translationPreview.previewId,acceptWarnings:!!$('#acceptTranslationWarnings')?.checked});toast(`${r.applied} traduções aplicadas; ${r.cached} reconhecidas no cache.`);state.translationPreview=null;translationsView();},
 'create-treasure-table':treasureTableEditor,
