const baseTranslationView=translationsView;translationsView=()=>{baseTranslationView();const n=$('#content .notice');if(n&&state.boot.translationConfig?.configured)n.textContent='Provedor LibreTranslate configurado: '+state.boot.translationConfig.url+'. Use o botão na ficha para traduzir o conteúdo. Traduções automáticas precisam de revisão; originais são preservados.';};
const baseCampaignView=campaignView;campaignView=()=>{baseCampaignView();const extra=state.entities.filter(x=>['inventory','spelllist'].includes(x.kind));if(extra.length)$('#content').insertAdjacentHTML('beforeend','<h2 class="section-title">Inventário e listas de magias</h2><div class="card">'+extra.map(x=>'<div class="entry-row"><div class="body"><h3>'+h(x.name)+'</h3><p>'+h(x.data.body||'')+(x.data.quantity?' · Quantidade '+x.data.quantity:'')+'</p></div>'+button('Abrir ficha','open-record','data-id="'+x.data.recordId+'"','small')+'</div>').join('')+'</div>');};

